CREATE TEMPORARY VIEW all_cspu_item_${grass_region_without_quote} AS
select
     cspu_id
    ,item_id
    ,mapping_general --这里不能是null或者''，还是要每个场景区分开，方便下游表自关联
from(
    select
          cspu_id
         ,item_id
    from srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf
    where grass_region = ${grass_region} and local_date = ${local_date}
    group by
          cspu_id
         ,item_id
) a
lateral view explode(array('RCMD','Search')) b as mapping_general -- 按照实验策略数量，进行维表复制拷贝，v3的第一次发版只有一个实验策略

;
--sql_divide_splitter--

CREATE TEMPORARY VIEW imp_click_${grass_region_without_quote} AS
select
     item_id
    ,mapping_general
    ,sum(imp_cnt)   as imp_cnt
    ,sum(click_cnt) as click_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(if(is_ads='true',0,imp_cnt)) org_imp_cnt
    ,sum(if(is_ads='true',0,click_cnt)) org_click_cnt
    ,sum(if(is_ads='true',0,order_cnt)) org_order_cnt
from(
    SELECT
         item_id
        ,is_ads
        ,case
           when (reporting_business_line in ('Search') and reporting_module in ('Global Search')) then 'Search'
           when (
                     (reporting_business_line = 'Rcmd' and reporting_module = 'User Scenario' and reporting_object = 'you may also like')
                  or (reporting_business_line = 'Homepage' and reporting_module = 'Daily Discover')
                  or (reporting_business_line = 'Rcmd' and reporting_module = 'User Scenario' and reporting_object = 'post purchase')
                 ) then 'RCMD'
         end as mapping_general
        ,imp_cnt
        ,click_cnt
        ,order_cnt
    FROM srdi_mart.dwm_sr_data_warehouse_tc_ab_all_cards
    WHERE grass_region IN (${grass_region}) AND local_date = ${local_date} and operation in ('omni_impression','omni_click','order')
    and (-- to reduce data size
        (
             (reporting_business_line = 'Rcmd' and reporting_module = 'User Scenario' and reporting_object = 'you may also like')
          or (reporting_business_line = 'Homepage' and reporting_module = 'Daily Discover')
          or (reporting_business_line = 'Rcmd' and reporting_module = 'User Scenario' and reporting_object = 'post purchase')
         )
    or
        (reporting_business_line in ('Search') and reporting_module in ('Global Search'))
    )
) a
group by
     item_id
    ,mapping_general
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_pb_itemcspu_1d PARTITION (grass_region = ${grass_region}, local_date = ${local_date})
select
     a.cspu_id
    ,a.item_id
    ,a.mapping_general
    ,b.imp_cnt
    ,b.click_cnt
    ,b.order_cnt
    ,b.org_imp_cnt
    ,b.org_click_cnt
    ,b.org_order_cnt
from all_cspu_item_${grass_region_without_quote} a
left join imp_click_${grass_region_without_quote} b on a.item_id=b.item_id and a.mapping_general=b.mapping_general
;
